typedef float rational_t;

class matrix4x4 { float m[16]; };
class vector3d { float x, y, z; };
class quaternion {
public:
  quaternion();
  quaternion(const matrix4x4&);
  quaternion& operator=(const quaternion&);
  void to_matrix(matrix4x4*) const;
};
struct qt { quaternion q; vector3d t; };
class po {
public:
  const matrix4x4& get_matrix() const;
  const vector3d& get_position() const;
};
class motion_blur_info {
public:
  int motion_trail_start;
  int motion_trail_end;
  int motion_trail_count;
  int motion_trail_length;
  int buffer_size;
  qt* motion_trail_buffer;
  vector3d motion_trail_head;
  vector3d motion_trail_tail;
  unsigned trail_color;
  int trail_min_alpha;
  int trail_max_alpha;
  int num_blur_images;
  rational_t blur_spread;
  rational_t last_motion_recording;
};
class entity {
  char padding0[332];
  motion_blur_info* mbi;
public:
  bool is_motion_blurred() const;
  bool is_motion_trailed() const;
  const po& get_abs_po() const;
  virtual void record_motion();
};
extern rational_t g_level_time;

void entity::record_motion()
{
  if(is_motion_blurred() || is_motion_trailed())
  {
    if( mbi->last_motion_recording != g_level_time )
    {
      mbi->motion_trail_buffer[mbi->motion_trail_end].q = quaternion(get_abs_po().get_matrix());
      matrix4x4 n;
      mbi->motion_trail_buffer[mbi->motion_trail_end].q.to_matrix( &n );
      mbi->motion_trail_buffer[mbi->motion_trail_end].t = get_abs_po().get_position();
      mbi->motion_trail_end++;
      if(mbi->motion_trail_end >= mbi->motion_trail_length)
        mbi->motion_trail_end = 0;
      if(mbi->motion_trail_count < mbi->motion_trail_length)
      {
        ++mbi->motion_trail_count;
      }
      else
      {
        mbi->motion_trail_start = mbi->motion_trail_end;
      }
      mbi->last_motion_recording = g_level_time;
    }
  }
}
